    maxRatio,
    greaterThan(minGrowthRatio),
    reason:
        '$label doubling ratio never exceeded ${minGrowthRatio}x '
        '(${maxRatio.toStringAsFixed(2)}x across $attempts attempts) — '
        'the measurement is degenerate and asserts nothing',
